def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            out[r][center-r] = 2
            out[r][center+r] = 2
        if r >= 3:
            for c in range(n):
                if (c-r-center) % 4 == 0 and (r > center or center-r <= c <= center+r):
                    out[r][c] = 1
        if r <= center:
            out[r][center-r] = out[r][center+r] = 2
    return out
if __name__ == '__main__':
